// Üretilen dosya: tool/ozgun/uret.py. Matematik · Polinomlar ve çarpanlara ayırma (zor).
const ozMathematics8Zor = <(String, String, List<String>, String)>[
  ('Altıncı kuvvetten (x + 1)⁶ ifadesi açılmadan, x³\'e bölündüğünde geriye kalan polinom bulunmak isteniyor. Bu kalan hangisidir?', '15x² + 6x + 1', ['20x³ + 15x² + 6x + 1', '6x + 1', '15x² + 6x'], 'x³ ile bölümde yalnız derecesi 3\'ten küçük terimler kalır. Açılımın son üç terimi C(6,2)x² + C(6,1)x + 1 = 15x² + 6x + 1\'dir.'),
  ('x²⁰²⁶ polinomu x² + 1 ile bölündüğünde kalan nedir?', '−1', ['1', 'x', '−x'], 'x² + 1 ile bölmede x² yerine −1 yazılabilir. x²⁰²⁶ = (x²)¹⁰¹³ olduğundan kalan (−1)¹⁰¹³ = −1 olur.'),
  ('Bir P(x) polinomunun x − 1, x − 2 ve x − 3 ile bölümünden kalanlar sırasıyla 1, 4 ve 9\'dur. P(x)\'in (x − 1)(x − 2)(x − 3) ile bölümünden kalan hangisidir?', 'x²', ['6x − 5', 'x² + 1', '3x − 2'], 'Kalan en çok ikinci dereceden olup R(1) = 1, R(2) = 4, R(3) = 9 koşullarını sağlamalıdır. Üç noktadan geçen en çok ikinci dereceden tek polinom x²\'dir.'),
  ('P(x) = (x² + 1)·Q(x) + x³ + 2x biçiminde yazılmış bir polinomun x² + 1 ile bölümünden kalan hangisidir?', 'x', ['x³ + 2x', '2x', 'x + 2'], 'x³ + 2x = x(x² + 1) + x olduğundan bu kısım da yeniden bölünür. Derecesi 2\'den küçük olan x, gerçek kalandır.'),
  ('2x³ − 3x² − 11x + 6 polinomunun tam sayı olmayan rasyonel kökü hangisidir?', '1/2', ['3/2', '−1/2', '2/3'], 'x = 3 denendiğinde 54 − 27 − 33 + 6 = 0 olur. Bölüm 2x² + 3x − 2 = (2x − 1)(x + 2) olduğundan kökler 3, −2 ve 1/2\'dir.'),
  ('x³ − 9x² + 23x − 15 polinomunun kökleri bir aritmetik dizinin ardışık üç terimidir. Ortadaki kök kaçtır?', '3', ['1', '5', '4,5'], 'Kökler a − d, a, a + d alınırsa toplamları 3a = 9 olur ve a = 3 bulunur. Gerçekten kökler 1, 3 ve 5\'tir.'),
  ('Gerçek katsayılı dördüncü dereceden bir polinomun katlılıkları ile sayılan gerçek kök sayısı aşağıdakilerden hangisi olamaz?', '3', ['0', '2', '4'], 'Gerçek olmayan kökler eşlenik çiftler hâlinde geldiğinden sayıları çifttir. 4 kökten 3\'ü gerçek olsaydı tek bir gerçek olmayan kök kalırdı; bu mümkün değildir.'),
  ('Tam sayı katsayılı bir P(x) polinomunda P(0) ve P(1) değerlerinin ikisi de tek sayıdır. P(x)\'in tam sayı kökleri için ne söylenebilir?', 'Hiç tam sayı kökü yoktur', ['Yalnız tek sayı kökleri olabilir', 'Yalnız çift sayı kökleri olabilir', 'En az bir tam sayı kökü vardır'], 'Tam sayı katsayılarda P(n)\'nin tek-çiftliği n\'nin tek-çiftliğine bağlıdır: çift n için P(n) ≡ P(0), tek n için P(n) ≡ P(1) (mod 2). İkisi de tek olduğundan P(n) hiçbir tam sayıda 0 olamaz.'),
  ('Tam sayı katsayılı bir P(x) polinomu için P(1) = 4\'tür. P(7) aşağıdakilerden hangisi olabilir?', '22', ['15', '20', '9'], 'Tam sayı katsayılı polinomlarda a − b sayısı P(a) − P(b) farkını böler. Bu yüzden 6, P(7) − 4\'ü bölmelidir; seçeneklerden yalnız 22 − 4 = 18 bu koşulu sağlar.'),
  ('x² − 4y² − x − 2y ifadesinde ilk iki terim ile son iki terim ayrı ayrı düzenlenirse ifade hangi çarpıma eşit olur?', '(x + 2y)(x − 2y − 1)', ['(x − 2y)(x + 2y − 1)', '(x + 2y)(x − 2y + 1)', '(x − 2y)(x − 2y − 1)'], 'x² − 4y² = (x − 2y)(x + 2y) ve −x − 2y = −(x + 2y) yazılır. Ortak çarpan x + 2y alınınca (x + 2y)(x − 2y − 1) çıkar.'),
  ('(a + b)³ − (a − b)³ farkı sadeleştirildiğinde hangi ifade elde edilir?', '6a²b + 2b³', ['2b³', '6ab² + 2a³', '2a³ + 6a²b + 2b³'], 'Açılımlar çıkarılınca a³ ve 3ab² terimleri birbirini götürür; 3a²b − (−3a²b) = 6a²b ve b³ − (−b³) = 2b³ kalır.'),
  ('x ve y gerçek sayıları için x² + y² − 4x + 6y + 13 = 0 ise x + y toplamı kaçtır?', '−1', ['1', '5', '−5'], 'İfade (x − 2)² + (y + 3)² = 0 biçiminde yazılır. İki karenin toplamı ancak ikisi de sıfırsa sıfırdır: x = 2, y = −3 ve toplam −1.'),
  ('Gerçek a ve b sayıları a² + b² + 2a − 4b + 5 = 0 eşitliğini sağlıyor. a·b çarpımı kaçtır?', '−2', ['2', '−1', '−4'], 'İfade (a + 1)² + (b − 2)² = 0 olarak düzenlenir. Bu yalnız a = −1 ve b = 2 için sağlanır; çarpım −2\'dir.'),
  ('x² + mx + 12 ifadesi tam sayı katsayılı iki birinci dereceden çarpana ayrılabiliyorsa m kaç farklı tam sayı değeri alabilir?', '6', ['3', '4', '12'], '12\'nin çarpanları (1, 12), (2, 6), (3, 4) ve bunların negatifleridir; toplamlar ±13, ±8, ±7 olur. Böylece m için 6 değer vardır.'),
  ('(x² + x)² − 8(x² + x) + 12 ifadesinin çarpanlarından biri aşağıdakilerden hangisidir?', 'x + 3', ['x − 3', 'x + 1', 'x − 6'], 't = x² + x denirse t² − 8t + 12 = (t − 2)(t − 6) olur. x² + x − 2 = (x + 2)(x − 1) ve x² + x − 6 = (x + 3)(x − 2) olduğundan x + 3 bir çarpandır.'),
  ('x⁴ + 2x³ + 3x² + 2x + 1 polinomu, katsayıları tam sayı olan ikinci dereceden bir polinomun karesidir. Bu polinom hangisidir?', 'x² + x + 1', ['x² + 2x + 1', 'x² − x + 1', 'x² + x + 2'], '(x² + x + 1)² = x⁴ + x² + 1 + 2x³ + 2x² + 2x = x⁴ + 2x³ + 3x² + 2x + 1 olur. Baş katsayı ve sabit terimden aday x² + ax + 1 alınıp x³ katsayısından a = 1 bulunur.'),
  ('Hem x hem y içeren 6x² + 5xy − 6y² homojen ifadesi hangi iki çarpana ayrılır?', '(2x + 3y)(3x − 2y)', ['(2x − 3y)(3x + 2y)', '(6x − y)(x + 6y)', '(3x + 3y)(2x − 2y)'], '(2x + 3y)(3x − 2y) = 6x² − 4xy + 9xy − 6y² = 6x² + 5xy − 6y² olur. İşaretleri ters olan seçenek orta terimi −5xy verir.'),
  ('x⁴ + x² + 1 ifadesi gerçek katsayılı ikinci dereceden iki çarpana ayrıldığında hangisi bulunur?', '(x² + x + 1)(x² − x + 1)', ['(x² + 1)² − x', '(x² + x − 1)(x² − x − 1)', '(x² + 1)(x² + x + 1)'], 'x⁴ + x² + 1 = (x⁴ + 2x² + 1) − x² = (x² + 1)² − x² yazılır ve iki kare farkı uygulanır.'),
  ('n pozitif tam sayı olmak üzere n⁴ + 4 sayısı hangi n değeri için asal olur?', 'Yalnız n = 1 için', ['Yalnız tek n değerleri için', 'Hiçbir n için', 'Yalnız n = 1 ve n = 3 için'], 'n⁴ + 4 = (n² + 2n + 2)(n² − 2n + 2)\'dir. İkinci çarpan (n − 1)² + 1 olduğundan yalnız n = 1\'de 1 olur ve sayı 5 asalı çıkar; diğer n\'lerde iki çarpan da 1\'den büyüktür.'),
  ('2³⁰ − 1 sayısı aşağıdakilerden hangisine tam bölünmez?', '5', ['7', '9', '31'], '2^d − 1, d\'nin 30\'u böldüğü her durumda 2³⁰ − 1\'i böler: 2³ − 1 = 7, 2⁵ − 1 = 31, 2⁶ − 1 = 63 = 7·9. 2\'nin kuvvetleri 5\'e göre 4 adımda tekrarlanır ve 2³⁰ ≡ 4 (mod 5) olduğundan 5 bölmez.'),
  ('x sayısı 1\'den büyüktür ve x ile 1/x\'in toplamı 4\'tür. x − 1/x farkı hangi değere eşittir?', '2√3', ['√14', '2√5', '√12 − 1'], '(x − 1/x)² = (x + 1/x)² − 4 = 16 − 4 = 12 olur. x > 1 olduğundan fark pozitiftir: √12 = 2√3.'),
  ('(x − y)³ + (y − z)³ + (z − x)³ toplamında parantezlerin toplamının sıfır olduğu fark edilirse ifade hangi çarpıma eşit çıkar?', '3(x − y)(y − z)(z − x)', ['(x − y)(y − z)(z − x)', '0', '3(x − y)²(z − x)'], 'Üç parantezin toplamı (x − y) + (y − z) + (z − x) = 0\'dır. Toplamı sıfır olan üç sayının küpleri toplamı çarpımlarının üç katıdır.'),
  ('Gerçek a, b, c sayıları için a² + b² + c² − ab − bc − ca = 0 ise aşağıdakilerden hangisi kesinlikle doğrudur?', 'a = b = c', ['a + b + c = 0', 'abc = 0', 'a = −b = c'], 'İfade ½[(a − b)² + (b − c)² + (c − a)²] biçiminde yazılır. Karelerin toplamı sıfırsa her biri sıfırdır; bu da a = b = c demektir.'),
  ('a ve b sıfırdan farklı ve a + b ≠ 0 olmak üzere (a/b − b/a)/(1/a + 1/b) ifadesi neye eşittir?', 'a − b', ['a + b', 'ab', '(a − b)/ab'], 'Pay (a² − b²)/ab, payda (a + b)/ab\'dir. Bölünce (a − b)(a + b)/(a + b) = a − b kalır.'),
  ('3x/((x − 1)(x + 2)) kesri A/(x − 1) + B/(x + 2) biçiminde basit kesirlere ayrılıyor. B kaçtır?', '2', ['1', '3', '−2'], '3x = A(x + 2) + B(x − 1) eşitliğinde x = −2 yazılırsa −6 = −3B ve B = 2 bulunur (x = 1 için de A = 1 çıkar).'),
  ('Monik P ve Q polinomlarının EBOB\'u x − 2, EKOK\'u (x − 2)(x + 1)(x + 3)\'tür. P(x) = (x − 2)(x + 1) ise Q(x) hangisidir?', '(x − 2)(x + 3)', ['(x + 1)(x + 3)', 'x + 3', '(x − 2)(x + 1)(x + 3)'], 'Monik polinomlarda EBOB·EKOK = P·Q\'dur. (x − 2)·(x − 2)(x + 1)(x + 3) = (x − 2)(x + 1)·Q eşitliğinden Q = (x − 2)(x + 3) bulunur.'),
  ('Gerçek katsayılı polinomlar içinde, gerçek katsayılı daha düşük dereceli çarpanlara ayrılamayan (indirgenemez) polinomların derecesi en çok kaçtır?', '2', ['1', '3', 'Sınır yoktur'], 'Cebirin temel teoremi ve eşlenik kökler nedeniyle her gerçek polinom birinci dereceden ve diskriminantı negatif ikinci dereceden çarpanlara ayrılır. Bu yüzden indirgenemez gerçek polinomlar en çok ikinci derecedendir.'),
  ('Karmaşık sayılar kümesinde indirgenemez olan polinomların derecesi kaçtır?', '1', ['2', '3', '0'], 'Cebirin temel teoremine göre derecesi 1\'den büyük her karmaşık polinomun bir kökü ve dolayısıyla birinci dereceden bir çarpanı vardır. Bu yüzden yalnız birinci derece polinomlar indirgenemezdir.'),
  ('x⁴ + 10x + 5 polinomunun rasyonel sayılarda indirgenemez olduğu Eisenstein ölçütüyle gösterilecektir. Ölçütte kullanılması gereken asal sayı hangisidir?', '5', ['2', '3', '7'], 'Eisenstein ölçütünde asal, baş katsayı dışındaki tüm katsayıları bölmeli, baş katsayıyı bölmemeli ve karesi sabit terimi bölmemelidir. 5, 10\'u ve 5\'i böler, 1\'i bölmez ve 25 de 5\'i bölmez.'),
  ('x³ − 2 polinomunun rasyonel katsayılı daha düşük dereceli çarpanlara ayrılamamasının gerekçesi nedir?', 'Üçüncü dereceden olup rasyonel kökü yoktur', ['Sabit terimi negatiftir', 'Baş katsayısı 1 olan bir polinomdur', 'Gerçek sayılarda hiç kökü bulunmayan bir polinomdur'], 'İkinci ya da üçüncü dereceden bir polinom ayrılabilseydi birinci dereceden bir çarpanı, yani rasyonel bir kökü olurdu. Adaylar ±1 ve ±2\'dir ve hiçbiri kök değildir.'),
  ('Derecesi en çok 3 olan bir P(x) polinomu beş farklı x değerinde sıfır oluyor. P(x) için hangisi kesinlikle doğrudur?', 'Sıfır polinomudur', ['Üçüncü derecedendir', 'Sabit terimi 5\'tir', 'Tam olarak üç kökü vardır'], 'Sıfırdan farklı ve derecesi en çok 3 olan bir polinomun en çok 3 kökü olabilir. Beş farklı kök olduğuna göre polinom sıfır polinomu olmak zorundadır.'),
  ('Horner yöntemine benzer sentetik bölme kuralı bazı ülkelerde hangi İtalyan matematikçinin adıyla anılır?', 'Paolo Ruffini', ['Gerolamo Cardano', 'Rafael Bombelli', 'Luca Pacioli'], 'Ruffini, 1804\'te sentetik bölme yöntemini açıklamıştır; bu nedenle yöntem İtalya ve İspanya gibi ülkelerde \'Ruffini kuralı\' olarak bilinir.'),
  ('x³ + px = q biçimindeki üçüncü dereceden denklemleri 16. yüzyılın başında ilk çözen, ancak yöntemini yayımlamayan Bolonyalı matematikçi kimdir?', 'Scipione del Ferro', ['Lodovico Ferrari', 'Niccolò Tartaglia', 'Rafael Bombelli'], 'Scipione del Ferro bu tür kübik denklemleri çözmüş, yöntemini öğrencisi Antonio Fior\'a bırakmıştır. Tartaglia aynı yöntemi daha sonra bağımsız olarak bulmuştur.'),
  ('n⁵ − n ifadesi her n tam sayısı için aşağıdakilerden hangisine kesinlikle bölünür?', '30', ['60', '24', '25'], 'n⁵ − n = (n − 1)n(n + 1)(n² + 1) çarpımında ardışık üç sayı 6\'ya bölünmeyi sağlar; 5\'e bölünebilme de n\'nin 5\'e göre kalanları denenerek görülür. n = 2 için değer 30 olduğundan 60, 24 ve 25 her zaman bölmez.'),
  ('2ⁿ − 1 sayısının asal olabilmesi için n\'nin asal olması gerekir. Bunun gerekçesi hangi çarpanlara ayırma bilgisine dayanır?', 'n = ab ise 2ᵃ − 1 sayısı 2ⁿ − 1\'i böler', ['2ⁿ − 1 her zaman tektir', 'n çiftse 2ⁿ − 1 tam karedir', 'n asal değilse 2ⁿ − 1 sayısı bir tam kare olur'], 'xᵇ − 1, x − 1\'e bölündüğünden x = 2ᵃ alınınca 2ᵃᵇ − 1 sayısı 2ᵃ − 1\'e bölünür. 1 < a < n ise bu, sayının asal olmadığını gösterir.'),
  ('Bir P(x) polinomu her gerçek x için P(x + 1) = P(x) eşitliğini sağlıyor. P(x) için hangisi kesinlikle doğrudur?', 'Sabit polinomdur', ['Birinci derecedendir', 'Tek dereceli terimleri yoktur', 'Kökü yoktur'], 'Q(x) = P(x) − P(0) polinomu 0, 1, 2, 3, … gibi sonsuz çoklukta noktada sıfır olur. Sonsuz kökü olan polinom sıfır polinomu olduğundan P(x) = P(0) sabittir.'),
  ('x = 1 + ∛2 sayısı x³ − 3x² + 3x + 5 polinomunda yerine konuyor. İfade bir küp ile bir sabitin toplamı biçimine getirilirse hangi sonuç elde edilir?', '8', ['7', '5', '6 + ∛2'], 'P(x) = (x − 1)³ + 6 biçiminde yazılır. x − 1 = ∛2 olduğundan P = 2 + 6 = 8 bulunur.'),
  ('Toplamları 3, kareleri toplamı 5 olan a ve b sayıları için dördüncü kuvvetlerinin toplamını bulunuz.', '17', ['25', '21', '13'], '(a + b)² = 9 = 5 + 2ab\'den ab = 2 bulunur. a⁴ + b⁴ = (a² + b²)² − 2a²b² = 25 − 8 = 17.'),
  ('Bir P(x) polinomu Horner yöntemiyle x − 1/2\'ye bölünerek Q(x) bölümü ve R kalanı bulunuyor. Aynı polinom 2x − 1\'e bölünürse bölüm ve kalan ne olur?', 'Bölüm Q(x)/2, kalan R', ['Bölüm Q(x), kalan R/2', 'Bölüm 2Q(x), kalan R', 'Bölüm Q(x)/2, kalan 2R'], 'P(x) = (x − 1/2)Q(x) + R = (2x − 1)·(Q(x)/2) + R yazılabilir. Bölen 2 katına çıkınca bölüm yarıya iner, kalan değişmez.'),
  ('x² + 1\'e bölündüğünde x + 2 kalanını veren bir P(x) için, x ile çarpılmış x·P(x) polinomu aynı bölene bölünürse geriye ne kalır?', '2x − 1', ['x² + 2x', '2x + 1', 'x − 2'], 'x·P(x) ifadesinin kalanı x(x + 2) = x² + 2x\'in kalanıyla aynıdır. x² yerine −1 yazılırsa 2x − 1 bulunur.'),
  ('x³ + y³ + x + y ifadesinde ortak çarpan olarak hangi iki terimli ortaya çıkar ve sonuç ne olur?', '(x + y)(x² − xy + y² + 1)', ['(x + y)(x² + xy + y² + 1)', '(x + y)(x² − xy + y²)', '(x + y)(x² − xy + y²) + x + y'], 'x³ + y³ = (x + y)(x² − xy + y²) olduğundan ifade (x + y)(x² − xy + y²) + (x + y) olur; x + y dışarı alınınca sonuç bulunur.'),
  ('x⁴ + 1 polinomu gerçek katsayılı çarpanlara ayrılabilir mi?', 'Evet: (x² + √2x + 1)(x² − √2x + 1)', ['Hayır, gerçek kökü olmadığı için ayrılamaz', 'Evet: (x² + 1)² − 2x² = (x² + 1)(x² − 1)', 'Evet: (x + 1)(x³ − x² + x + 1)'], 'x⁴ + 1 = (x² + 1)² − 2x² = (x² + 1 − √2x)(x² + 1 + √2x) olur. Gerçek kökü olmasa da ikinci dereceden gerçek çarpanlara ayrılır.'),
  ('x⁴ − x³ − x + 1 dört terimlisinde ilk iki ve son iki terim gruplanıp küp farkı da kullanılırsa sonuç ne olur?', '(x − 1)²(x² + x + 1)', ['(x − 1)(x³ + 1)', '(x + 1)²(x² − x + 1)', '(x − 1)²(x + 1)(x² + x + 1)'], 'x³(x − 1) − (x − 1) = (x − 1)(x³ − 1) ve x³ − 1 = (x − 1)(x² + x + 1) olduğundan (x − 1)²(x² + x + 1) çıkar.'),
  ('Heron formülünün türetilmesinde geçen 4a²b² − (a² + b² − c²)² ifadesi birinci dereceden çarpanlara ayrıldığında kaç çarpan elde edilir?', '4', ['2', '3', '12'], 'İki kare farkı (2ab − a² − b² + c²)(2ab + a² + b² − c²) verir; bunlar c² − (a − b)² ve (a + b)² − c² olarak yeniden ayrılır: (b + c − a)(a − b + c)(a + b − c)(a + b + c).'),
  ('P(x) + Q(x) toplamının derecesi 4, P(x) − Q(x) farkının derecesi 2\'dir. P(x) polinomunun derecesi kaçtır?', '4', ['2', '3', '6'], 'P ve Q\'dan biri 4\'ten küçük dereceli olsaydı fark da 4. dereceden olurdu. Farkta x⁴ yok olduğuna göre ikisi de 4. derecedendir ve x⁴ katsayıları eşittir.'),
  ('n. dereceden bir polinomun bir noktadaki değeri Horner (iç içe çarpım) yöntemiyle hesaplanırsa en çok kaç çarpma işlemi gerekir?', 'n', ['2n', 'n²', 'n(n + 1)/2'], 'Horner yönteminde her adımda bir çarpma ve bir toplama yapılır; n. derecede n adım vardır. Terimleri ayrı ayrı kuvvet alarak hesaplamak çok daha fazla çarpma gerektirir.'),
  ('2x³ − 5x² + 3x − 7 polinomunun köklerinin çarpmaya göre terslerini kök kabul eden polinom aşağıdakilerden hangisidir?', '−7x³ + 3x² − 5x + 2', ['−7x³ − 3x² + 5x + 2', '2x³ − 3x² + 5x − 7', '−7x³ + 5x² − 3x + 2'], 'r kök ise 1/r için P(1/x) = 0 olmalıdır; x³ ile çarpılınca katsayılar ters sırada yazılmış polinom elde edilir: −7x³ + 3x² − 5x + 2.'),
  ('(a² + b²)(c² + d²) = (ac − bd)² + (ad + bc)² özdeşliği a = 1, b = 2, c = 2, d = 3 için uygulanırsa 65 sayısı hangi iki karenin toplamı olarak yazılır?', '4² + 7²', ['2² + 9²', '3² + 8²', '5² + 6²'], 'ac − bd = 2 − 6 = −4 ve ad + bc = 3 + 4 = 7\'dir. (−4)² + 7² = 16 + 49 = 65 olur; diğer seçeneklerin toplamları 85, 73 ve 61\'dir.'),
  ('Kübik denklemlerin çözümünde ortaya çıkan negatif sayıların karekökleriyle hesap yapma kurallarını 1572\'de L\'Algebra adlı eserinde ilk kez sistemli biçimde veren İtalyan matematikçi kimdir?', 'Rafael Bombelli', ['Gerolamo Cardano', 'Lodovico Ferrari', 'Luca Pacioli'], 'Bombelli, Cardano formülünün gerçek kökleri bile karmaşık ara sonuçlarla verdiği durumları incelemiş ve bu sayılarla işlem kurallarını L\'Algebra\'da açıklamıştır.'),
  ('Altıncı dereceden a⁶ + 2a³ + 1 ifadesi önce a³ cinsinden bir tam kare olarak görülüp sonra küp toplamıyla ayrılırsa ne elde edilir?', '(a + 1)²(a² − a + 1)²', ['(a³ + 1)(a³ − 1)', '(a + 1)⁶', '(a + 1)(a² − a + 1)(a³ − 1)'], 'İfade (a³ + 1)²\'dir. a³ + 1 = (a + 1)(a² − a + 1) olduğundan karesi (a + 1)²(a² − a + 1)² olur.'),
  ('Bir dikdörtgenler prizmasının üç farklı ayrıt uzunluğunun toplamı 12 cm, yüzey alanı 94 cm²\'dir. Cisim köşegeninin uzunluğu kaç cm\'dir?', '5√2', ['5√3', '10', '√50 + 2'], 'a + b + c = 12 ve 2(ab + bc + ca) = 94\'tür. a² + b² + c² = 144 − 94 = 50 olduğundan köşegen √50 = 5√2 cm\'dir.'),
  ('(1 + x + x²)³ ifadesi açıldığında x²\'li terimin katsayısı kaçtır?', '6', ['3', '7', '27'], 'x², üç çarpandan birinden x² ve diğerlerinden 1 seçilerek (3 yol) ya da ikisinden x ve birinden 1 seçilerek (3 yol) elde edilir: 3 + 3 = 6.'),
  ('Bir polinomda tek dereceli terimlerin katsayıları toplamı, çift dereceli terimlerin katsayıları toplamına (sabit terim dâhil) eşittir. Hangisi kesinlikle bir çarpandır?', 'x + 1', ['x − 1', 'x', 'x² + 1'], 'P(−1), çift dereceli katsayılar toplamından tek dereceli katsayılar toplamının çıkarılmasıyla bulunur. Bu iki toplam eşitse P(−1) = 0 ve x + 1 çarpandır.'),
  ('x + y = 1 eşitliğini sağlayan bütün gerçek x, y sayıları için x³ + y³ + 3xy ifadesinin değeri kaçtır?', '1', ['0', '3', 'x + y + 3'], 'x³ + y³ = (x + y)³ − 3xy(x + y) = 1 − 3xy olduğundan ifade 1 − 3xy + 3xy = 1\'dir.'),
  ('a²b² − 1 + a² − b² ifadesi uygun gruplandırmayla hangi çarpıma ayrılır?', '(a − 1)(a + 1)(b² + 1)', ['(ab − 1)(ab + 1)', '(a² + 1)(b − 1)(b + 1)', '(ab − 1)(ab + 1)(a² + 1)'], 'a²b² + a² = a²(b² + 1) ve −b² − 1 = −(b² + 1) gruplanınca (a² − 1)(b² + 1) = (a − 1)(a + 1)(b² + 1) bulunur.'),
  ('xy + x + y = 11 denkleminin iki yanına 1 eklenip sol taraf çarpanlarına ayrılırsa, pozitif tam sayılarda kaç sıralı (x, y) çözümü bulunur?', '4', ['2', '3', '12'], 'Her iki tarafa 1 eklenirse (x + 1)(y + 1) = 12 olur. x + 1 ve y + 1 en az 2 olmalıdır: (2, 6), (3, 4), (4, 3), (6, 2) çiftleri dört ikili verir.'),
  ('Her kökün a³ = 3a − 1 eşitliğini sağladığı x³ − 3x + 1 polinomunda, köklerin küpleri toplanırsa sonuç ne olur?', '−3', ['3', '0', '−27'], 'Her kök a³ = 3a − 1 eşitliğini sağlar. Toplanınca a³ + b³ + c³ = 3(a + b + c) − 3 = 3·0 − 3 = −3 olur.'),
  ('x³ − 2x² + 3x − 4 polinomunun kökleri a, b ve c\'dir. (1 − a)(1 − b)(1 − c) çarpımı kaçtır?', '−2', ['2', '−4', '−24'], 'Baş katsayısı 1 olduğundan P(x) = (x − a)(x − b)(x − c) yazılır. Aranan çarpım P(1) = 1 − 2 + 3 − 4 = −2\'dir.'),
  ('cos(nθ) ifadesini cos θ\'nın bir polinomu olarak veren polinom ailesi hangi matematikçinin adıyla anılır?', 'Chebyshev', ['Legendre', 'Hermite', 'Bernoulli'], 'Tₙ(cos θ) = cos(nθ) bağıntısını sağlayan polinomlar Chebyshev polinomlarıdır; örneğin T₂(x) = 2x² − 1.'),
  ('x⁴ − 1 ve x⁶ − 1 polinomlarının en büyük ortak böleni hangisidir?', 'x² − 1', ['x − 1', 'x² + 1', 'x¹² − 1'], 'xᵃ − 1 ile xᵇ − 1\'in EBOB\'u x^EBOB(a, b) − 1\'dir. EBOB(4, 6) = 2 olduğundan sonuç x² − 1\'dir.'),
  ('Sabit olmayan gerçek katsayılı bir polinom her gerçek x için pozitif değer alıyorsa derecesi için ne söylenebilir?', 'Çift sayıdır', ['Tek sayıdır', '1\'dir', '3\'ten büyüktür'], 'Tek dereceli gerçek polinomlar bir yönde +∞\'a, öbür yönde −∞\'a gider ve arada sıfırdan geçer. Hiç kökü olmadığına göre derece çift olmalıdır.'),
  ('İki polinomun çarpımı sıfır polinomu ise aşağıdakilerden hangisi kesinlikle doğrudur?', 'Polinomlardan en az biri sıfır polinomudur', ['İkisi de sabit polinomdur', 'Dereceleri toplamı sıfırdır', 'İkisinin de kökleri ortaktır ve aynı derecededir'], 'Sıfırdan farklı iki polinomun çarpımının baş katsayısı, baş katsayıların çarpımıdır ve sıfır olamaz. Bu yüzden çarpım sıfırsa çarpanlardan biri sıfır polinomudur.'),
  ('Sıfırdan farklı a, b, c sayıları için 1/a + 1/b + 1/c = 0 ise hangisi her zaman doğrudur?', '(a + b + c)² = a² + b² + c²', ['a + b + c = 0', 'abc = 1', 'a² + b² + c² = ab + bc + ca'], 'Paydalar eşitlenince (ab + bc + ca)/abc = 0, yani ab + bc + ca = 0 olur. Bu yüzden (a + b + c)² açılımındaki 2(ab + bc + ca) terimi sıfırdır.'),
  ('Ardışık farkları a − b = 2 ve b − c = 2 olan üç sayı için a² + b² + c² − ab − bc − ca hesaplanırsa ne bulunur?', '12', ['8', '4', '−12'], 'İfade ½[(a − b)² + (b − c)² + (c − a)²]\'dir. c − a = −4 olduğundan ½(4 + 4 + 16) = 12 bulunur.'),
  ('(a² + b²)(c² + d²) − (ac + bd)² farkı hangi ifadeye eşittir?', '(ad − bc)²', ['(ad + bc)²', '(ab − cd)²', '(ac − bd)² + 2abcd'], 'Açılımda a²c² ve b²d² terimleri sadeleşir; geriye a²d² + b²c² − 2abcd = (ad − bc)² kalır. Bu Lagrange özdeşliği Cauchy–Schwarz eşitsizliğinin iki boyutlu hâlini verir.'),
  ('(a² + b²)(c² + d²) çarpımının da iki karenin toplamı olarak yazılabileceğini gösteren özdeşlik hangi adlarla anılır?', 'Brahmagupta–Fibonacci özdeşliği', ['Sophie Germain özdeşliği', 'Pascal özdeşliği', 'Cauchy–Schwarz–Bunyakovski eşitsizliği'], 'Bu özdeşlik Hintli matematikçi Brahmagupta\'nın çalışmalarında görülür ve Fibonacci\'nin 1225 tarihli Liber Quadratorum\'unda yer aldığı için iki adla birlikte anılır.'),
  ('x² + x − 1 = 0 eşitliğini sağlayan x için x³ + 2x² + 2026 ifadesinin değeri kaçtır?', '2027', ['2026', '2025', '−2027'], 'x² = 1 − x olduğundan x³ = x − x² olur. x³ + 2x² = x + x² = 1 bulunur; sonuç 1 + 2026 = 2027.'),
  ('x² = x + 1 eşitliğini sağlayan bir x için x⁴ hangi birinci dereceden ifadeye eşittir?', '3x + 2', ['2x + 1', 'x + 2', '3x + 2 + x²'], 'x⁴ = (x²)² = (x + 1)² = x² + 2x + 1 olur. x² yerine yeniden x + 1 yazılınca 3x + 2 bulunur.'),
  ('x² + x + 1 ifadesinin karesi, yani (x² + x + 1)², x² + x ile bölündüğünde kalan kaçtır?', '1', ['x + 1', '0', 'x² + 1'], 'Bölmede x² + x yerine 0 yazılabilir; o zaman x² + x + 1 ifadesi 1 olur ve karesi de 1\'dir. Kalan sabit 1\'dir.'),
  ('x⁴ − 11x² + 1 ifadesi (x² − 1)² − 9x² biçiminde yazılırsa hangi çarpıma ayrılır?', '(x² − 3x − 1)(x² + 3x − 1)', ['(x² − 3x + 1)(x² + 3x + 1)', '(x² − 1)(x² − 10)', '(x² − 3x − 1)(x² + 3x − 1)(x² + 1)'], '(x² − 1)² = x⁴ − 2x² + 1 olduğundan 9x² çıkarılınca x⁴ − 11x² + 1 elde edilir. İki kare farkıyla (x² − 1 − 3x)(x² − 1 + 3x) bulunur.'),
  ('Döngüsel x²(y − z) + y²(z − x) + z²(x − y) toplamında x = y yazılınca sıfır çıktığı fark ediliyor. Bu toplam hangi çarpıma eşittir?', '−(x − y)(y − z)(z − x)', ['(x − y)(y − z)(z − x)', '(x + y)(y + z)(z + x)', '−(x − y)(y − z)(z − x)xyz'], 'x = y alındığında ifade sıfır olduğundan x − y bir çarpandır; benzer biçimde y − z ve z − x de çarpandır. x = 0, y = 1, z = 2 denemesi işaretin eksi olduğunu gösterir.'),
  ('a, b, c birbirinden farklı sayılar olmak üzere 1/((a − b)(a − c)) + 1/((b − a)(b − c)) + 1/((c − a)(c − b)) toplamı kaçtır?', '0', ['1', 'abc', '1/(abc)'], 'Ortak payda (a − b)(b − c)(c − a) alınınca pay −(b − c) − (c − a) − (a − b) = 0 olur. Toplam her zaman sıfırdır.'),
  ('Kökleri −2 ve 2 olan P(x) = x² − 4 polinomu için P(x²) polinomunun gerçek kökleri hangileridir?', '−√2 ve √2', ['−2 ve 2', '−4 ve 4', '−16 ve 16'], 'P(x²) = x⁴ − 4 = (x² − 2)(x² + 2) olur. x² = 2 gerçek kökleri ±√2 verir; x² = −2 gerçek kök vermez.'),
  ('n bir tam sayı olmak üzere n³ + 2n ifadesi her zaman hangi sayıya bölünür?', '3', ['2', '4', '15'], 'n³ + 2n = (n³ − n) + 3n yazılır. n³ − n = (n − 1)n(n + 1) ardışık üç sayının çarpımı olduğundan 3\'e bölünür; 3n de 3\'ün katıdır.'),
  ('(a + b)³ = a³ + b³ eşitliği aşağıdaki durumlardan hangisinde de sağlanır?', 'a = −b olduğunda', ['a = b olduğunda', 'a = 2b olduğunda', 'a + b = 1 olduğunda'], '(a + b)³ − (a³ + b³) = 3ab(a + b)\'dir. Fark a = 0, b = 0 ya da a + b = 0 olduğunda sıfırdır.'),
  ('Rasyonel katsayılı ve baş katsayısı 1 olan, köklerinden biri √2 + √3 olan en küçük dereceli polinomun derecesi kaçtır?', '4', ['2', '3', '16'], 'x = √2 + √3 ise x² = 5 + 2√6 ve (x² − 5)² = 24 olur. Buradan x⁴ − 10x² + 1 = 0 bulunur; bu polinom rasyonel sayılarda daha alçak dereceli çarpanlara ayrılmaz.'),
  ('Üç farklı gerçek kökü olan kübik denklemlerde Cardano formülünün ara adımlarda karmaşık sayılarla işlem yapmayı zorunlu kıldığı duruma ne ad verilir?', 'Casus irreducibilis', ['Reductio ad absurdum', 'Abel–Ruffini durumu', 'Galois grubu'], 'Latince \'indirgenemez durum\' anlamına gelen casus irreducibilis, kökler gerçek olsa bile formülün negatif sayıların kareköklerini içermesidir; Bombelli bu sayılarla hesap yapmanın yolunu göstermiştir.'),
  ('Birinci dereceden bir P(x) polinomu her x için P(P(x)) = x + 2 eşitliğini sağlıyor. P(x) hangisidir?', 'x + 1', ['x + 2', '2x + 1', '−x + 1'], 'P(x) = ax + b ise P(P(x)) = a²x + ab + b olur. a² = 1 ve b(a + 1) = 2\'dir; a = −1 bu eşitliği sağlamadığından a = 1, b = 1 bulunur.'),
  ('Bir sayının 11\'e bölünebilmesi için rakamların sağdan başlayarak +, −, +, … işaretleriyle toplanması kuralı, sayıyı P(10) biçiminde yazan polinom için hangi gerçeğe dayanır?', 'P(10) ile P(−1)\'in 11\'e göre denk olması', ['P(10) ile P(1)\'in 11\'e göre denk olması', 'P(10) ile P(0)\'ın eşit olması', '11\'in asal sayı olması'], 'P(10) − P(−1) farkı 10 − (−1) = 11\'e bölünür. Bu yüzden sayı ile işaretli rakam toplamı P(−1) aynı kalanı verir.'),
  ('Eşitsizlik işaretlerini (< ve >) ilk kullanan ve denklemleri sıfıra eşitleyip birinci dereceden çarpanların çarpımı olarak yazma yöntemini geliştiren İngiliz matematikçi kimdir?', 'Thomas Harriot', ['Robert Recorde', 'John Napier', 'William Oughtred'], 'Harriot\'un ölümünden sonra 1631\'de yayımlanan Artis Analyticae Praxis adlı eserinde hem < ve > işaretleri hem de polinomları çarpanlar biçiminde yazma yaklaşımı yer alır.'),
  ('Gerçek katsayılı polinomlar arasında çarpmaya göre tersi de bir polinom olan elemanlar hangileridir?', 'Sıfır olmayan sabitler', ['Birinci dereceden polinomlar', 'Baş katsayısı 1 olanlar', 'Bütün sıfırdan farklı polinomlar'], 'P·Q = 1 olması için derecelerin toplamı 0 olmalıdır; bu ancak ikisi de sıfırdan farklı sabit olduğunda mümkündür. Örneğin x\'in tersi 1/x polinom değildir.'),
  ('Rasyonel kök denemesinde x = 1\'in kök olduğu görülen 4x³ − 3x − 1 polinomunda iki kez tekrarlanan kök hangisidir?', '−1/2', ['1', '1/2', '−1/4'], 'x = 1 köktür; bölüm 4x² + 4x + 1 = (2x + 1)² çıkar. Böylece −1/2 çift katlı köktür.'),
  ('1/(x(x + 1)) + 1/((x + 1)(x + 2)) toplamının en sade hâli hangisidir?', '2/(x(x + 2))', ['1/(x(x + 2))', '2/((x + 1)(x + 2))', '(2x + 2)/(x(x + 2))'], 'Her kesir iki terimin farkına ayrılır: (1/x − 1/(x + 1)) + (1/(x + 1) − 1/(x + 2)) = 1/x − 1/(x + 2) = 2/(x(x + 2)).'),
  ('x⁴ + x³ + x² + x + 1 = 0 denkleminin her kökü aşağıdaki eşitliklerden hangisini sağlar?', 'x⁵ = 1', ['x⁴ = 1', 'x⁵ = −1', 'x³ = 1'], '(x − 1)(x⁴ + x³ + x² + x + 1) = x⁵ − 1 olduğundan bu polinomun her kökü x⁵ − 1 = 0\'ı da sağlar; kökler 1 dışındaki beşinci birim köklerdir.'),
  ('x⁸ + x⁴ + 1 ifadesi tam sayı katsayılı, daha fazla ayrılamayan çarpanlara ayrıldığında kaç çarpan elde edilir?', '3', ['2', '4', '1'], 'x⁸ + x⁴ + 1 = (x⁴ + x² + 1)(x⁴ − x² + 1) ve x⁴ + x² + 1 = (x² + x + 1)(x² − x + 1)\'dir. Sonuç üç çarpandır.'),
  ('(a² − 1)(b² − 1) − (ab − 1)² ifadesi sadeleştirildiğinde hangisi bulunur?', '−(a − b)²', ['(a − b)²', '−(a + b)²', '2ab − 2'], 'İlk çarpım a²b² − a² − b² + 1, ikincisi a²b² − 2ab + 1\'dir. Fark −a² − b² + 2ab = −(a − b)² olur.'),
  ('İç içe kesir (a + 1/b)/(b + 1/a), ab ≠ −1 ve a, b ≠ 0 iken hangi basit orana indirgenir?', 'a/b', ['b/a', 'ab', '(ab + 1)/b'], 'Pay (ab + 1)/b, payda (ab + 1)/a\'dır. Bölününce a/b kalır.'),
  ('Bir öğrenci √(x² + 2x + 1) = x + 1 eşitliğinin her gerçek x için doğru olduğunu söylüyor. Doğru olan hangisidir?', 'Eşitlik yalnız x ≥ −1 için doğrudur', ['Eşitlik her x için doğrudur', 'Eşitlik hiçbir x için doğru değildir', 'Eşitlik yalnız x = −1 için doğrudur'], '√((x + 1)²) = |x + 1|\'dir. Bu değer x + 1\'e ancak x + 1 ≥ 0 iken eşittir; örneğin x = −3\'te sol taraf 2, sağ taraf −2\'dir.'),
  ('x³ + 3x² + 3x + 2 polinomu (x + 1)³ + 1 biçiminde yazılarak hangi çarpıma ayrılır?', '(x + 2)(x² + x + 1)', ['(x + 1)(x² + 2x + 2)', '(x + 2)(x² − x + 1)', '(x + 2)³'], 'a = x + 1 ile a³ + 1 = (a + 1)(a² − a + 1) olur. a + 1 = x + 2 ve a² − a + 1 = x² + 2x + 1 − x − 1 + 1 = x² + x + 1\'dir.'),
  ('(x − 3)(x − 1)(x + 1)(x + 3) + 16 ifadesi hangi ifadenin karesine eşittir?', 'x² − 5', ['x² − 4', 'x² + 5', 'x² − 3x + 5'], 'Çarpanlar (x − 3)(x + 3) = x² − 9 ve (x − 1)(x + 1) = x² − 1 olarak eşleştirilir. (x² − 9)(x² − 1) + 16 = x⁴ − 10x² + 25 = (x² − 5)².'),
  ('Dört tam karenin toplamı biçiminde yazılabilen iki sayının çarpımının da dört karenin toplamı olarak yazılabileceğini gösteren özdeşlik hangi matematikçinin adıyla anılır?', 'Leonhard Euler', ['Sophie Germain', 'Brahmagupta', 'Joseph-Louis Lagrange'], 'Euler\'in dört kare özdeşliği 1748\'de bir mektupta yer almıştır; Lagrange daha sonra her doğal sayının dört karenin toplamı olduğunu kanıtlarken bu özdeşlikten yararlanmıştır.'),
  ('Bir polinomun köklerinin kuvvet toplamlarını (x₁ᵏ + x₂ᵏ + …) katsayılarla ilişkilendiren bağıntılar hangi matematikçinin adıyla anılır?', 'Isaac Newton', ['François Viète', 'René Descartes', 'Carl Friedrich Gauss'], 'Newton özdeşlikleri kuvvet toplamlarını kökler toplamı, ikişerli çarpımlar toplamı gibi temel simetrik ifadelere bağlar. Viète formülleri ise bu temel ifadeleri katsayılara bağlar.'),
  ('Horner yöntemine çok benzeyen bir sayısal yöntemi 1247 tarihli eserinde yüksek dereceli denklemleri çözmek için kullanan Çinli matematikçi kimdir?', 'Qin Jiushao', ['Liu Hui', 'Zu Chongzhi', 'Yang Hui'], 'Qin Jiushao\'nun \'Dokuz Bölümde Matematik Üzerine İnceleme\' adlı eseri, katsayılarla ardışık çarpma-toplama yapan ve Horner yöntemine denk düşen bir hesap düzeni içerir.'),
  ('(x² + ax + 2)(x² + bx + 3) çarpımında x³\'lü terimin katsayısı 5, x\'li terimin katsayısı 7\'dir. a·b çarpımı kaçtır?', '−24', ['24', '−15', '10'], 'x³ katsayısı a + b = 5, x katsayısı 3a + 2b = 7\'dir. Çözülünce a = −3, b = 8 ve a·b = −24 bulunur.'),
  ('a + b + c = 3 ve a² + b² + c² = 3 koşullarını sağlayan gerçek a, b, c sayıları için abc çarpımı kaçtır?', '1', ['3', '0', '9'], '(a + b + c)² = 9\'dan ab + bc + ca = 3 bulunur. a² + b² + c² − ab − bc − ca = 0 olduğundan a = b = c = 1\'dir.'),
  ('(x + 1)(x² + 1)(x⁴ + 1) çarpımı açılıp benzer terimler toplandığında kaç terim elde edilir?', '8', ['7', '6', '3'], 'Çarpım 1 + x + x² + ⋯ + x⁷ olur; 0\'dan 7\'ye kadar her üs tam bir kez oluşur. Bu, her doğal sayının ikilik tabanda tek türlü yazılmasıyla da açıklanır.'),
  ('Yüzüncü kuvvet x¹⁰⁰, x yerine (x − 1) + 1 yazılarak (x − 1)²\'ye bölünürse geriye hangi birinci derece ifade kalır?', '100x − 99', ['1', '100x + 1', 'x − 99'], 'x = (x − 1) + 1 yazılıp açılırsa (x − 1)² ve daha yüksek kuvvetleri içeren terimler bölünür; geriye 1 + 100(x − 1) = 100x − 99 kalır.'),
  ('x ve y tam sayılar olmak üzere x³ − y³ = 26 ve x − y = 2 ise x·y çarpımı kaçtır?', '3', ['13', '6', '−3'], 'x² + xy + y² = 26/2 = 13\'tür. (x − y)² = x² − 2xy + y² = 4 olduğundan 3xy = 13 − 4 = 9 ve xy = 3 bulunur.'),
  ('Tanımlı olduğu değerler için 1 − 1/(1 − 1/(1 − x)) iç içe kesrinin en sade biçimi hangisidir?', '1/x', ['x', '1 − x', 'x/(x − 1)'], '1 − 1/(1 − x) = −x/(1 − x) olur; bunun tersi (x − 1)/x\'tir. 1 − (x − 1)/x = 1/x bulunur.'),
  ('Kuvvetleri sınırsız sürdürüp polinomlarla aritmetikteki gibi işlem yapan ve binom katsayıları tablosunu kullanan 10–11. yüzyıl Bağdatlı matematikçi kimdir?', 'el-Kerecî', ['el-Harezmî', 'Ömer Hayyam', 'Sâbit bin Kurre'], 'El-Kerecî (al-Karaji), cebiri geometriden bağımsız biçimde polinom işlemleriyle ele almış ve binom katsayılarını içeren tabloyu kullanmıştır.'),
  ('x⁴ + 3x³ − 8x² + 3x + 1 = 0 denklemi x²\'ye bölünüp t = x + 1/x dönüşümü yapılırsa t için hangi denklem elde edilir?', 't² + 3t − 10 = 0', ['t² + 3t − 8 = 0', 't² + 3t − 6 = 0', 't² − 3t − 10 = 0'], 'x² + 1/x² = t² − 2 olduğundan (t² − 2) + 3t − 8 = 0, yani t² + 3t − 10 = 0 bulunur.'),
  ('Gerçek katsayılı monik bir polinomun indirgenemez monik çarpanlara ayrılışı için hangisi doğrudur?', 'Çarpanların sırası dışında tek türlüdür', ['Her zaman iki farklı biçimde yapılabilir', 'Yalnız ikinci dereceden polinomlarda tek türlüdür', 'Hiçbir zaman tek türlü değildir'], 'Tam sayıların asal çarpanlara ayrılışında olduğu gibi, bir cisim üzerindeki polinomların indirgenemez çarpanlara ayrılışı sıra dışında tektir.'),
  ('Katsayıları tam sayılar olan x değişkenli bütün polinomların kümesi genellikle nasıl gösterilir?', 'ℤ[x]', ['ℤ(x)', 'ℕ[x]', 'x[ℤ]'], 'Katsayı kümesi köşeli parantezli değişkenin önüne yazılır: ℤ[x] tam sayı, ℚ[x] rasyonel, ℝ[x] gerçek katsayılı polinomları gösterir.'),
  ('x sayısı −3 ile 3 arasında (uçlar dâhil) değişirken √(x² + 6x + 9) + √(x² − 6x + 9) toplamı hep aynı kalır. Bu sabit değer nedir?', '6', ['2x', '0', '2x + 6'], 'Kök içleri (x + 3)² ve (x − 3)²\'dir. Toplam |x + 3| + |x − 3| = (x + 3) + (3 − x) = 6 olur.'),
  ('a³ + b³ + 1 − 3ab ifadesinin birinci dereceden çarpanı aşağıdakilerden hangisidir?', 'a + b + 1', ['a + b − 1', 'a − b + 1', 'ab + 1'], 'x³ + y³ + z³ − 3xyz = (x + y + z)(x² + y² + z² − xy − yz − zx) özdeşliğinde z = 1 alınırsa a + b + 1 çarpanı ortaya çıkar.'),
  ('x³ − 3x − 2 polinomunun birbirinden farklı gerçek köklerinin toplamı kaçtır?', '1', ['0', '3', '−1'], 'Polinom (x + 1)²(x − 2) biçiminde ayrılır. Farklı kökler −1 ve 2\'dir; toplamları 1\'dir. Kökler toplamının 0 çıkması, −1\'in iki kez sayılmasındandır.'),
  ('√(7 + 4√3) ifadesi hangi sayıya eşittir?', '2 + √3', ['√7 + 2', '3 + √3', '1 + 2√3'], '(2 + √3)² = 4 + 4√3 + 3 = 7 + 4√3 olduğundan karekök 2 + √3\'tür; tam kare özdeşliği iç içe kökü sadeleştirir.'),
  ('x ve y gerçek sayılar olmak üzere x² + xy + y² = 0 eşitliğini sağlayan kaç (x, y) ikilisi vardır?', '1', ['0', '2', 'Sonsuz sayıda'], 'x² + xy + y² = (x + y/2)² + 3y²/4 olduğundan ifade ancak y = 0 ve x = 0 için sıfırdır.'),
  ('x⁶ − 1 tamamen çarpanlarına ayrılırken ilk adımda iki kare farkı mı yoksa iki küp farkı mı kullanılmalıdır?', 'İki kare farkı: (x³ − 1)(x³ + 1)', ['İki küp farkı: (x² − 1)(x⁴ + x² + 1)', 'İkisi aynı sonucu aynı kolaylıkla verir', 'Ortak çarpan parantezi alınmalıdır'], 'Kare farkıyla elde edilen x³ − 1 ve x³ + 1 doğrudan küp formülleriyle ayrılır. Küp farkıyla başlanırsa x⁴ + x² + 1\'in ayrılması için ek bir terim ekleme adımı gerekir.'),
  ('Birbirinin eşleniği olan √2 + 1 ve √2 − 1 sayılarının küplerinin toplamı, toplam ve çarpım kullanılarak hesaplanırsa ne bulunur?', '10√2', ['16√2', '6√2', '14'], 'x + y = 2√2 ve xy = 2 − 1 = 1\'dir. x³ + y³ = (x + y)³ − 3xy(x + y) = 16√2 − 6√2 = 10√2.'),
  ('İki küpkökün toplamı olan ∛(2 + √5) + ∛(2 − √5) sayısına s denip s³ hesaplanırsa s\'nin değeri ne çıkar?', '1', ['∛4', '2', '0'], 'Toplama s denirse s³ = 4 + 3·∛(4 − 5)·s = 4 − 3s olur. s³ + 3s − 4 = (s − 1)(s² + s + 4) = 0 ve tek gerçek çözüm s = 1\'dir.'),
  ('(x + 1)⁵ − x⁵ − 1 polinomu x = 0 ve x = −1\'de sıfır olur. Seçeneklerden hangisi bu polinomu tam bölmez?', 'x − 1', ['x', 'x + 1', 'x² + x + 1'], 'Polinom 5x(x + 1)(x² + x + 1) biçiminde ayrılır. x = 1 için değeri 32 − 2 = 30 ≠ 0 olduğundan x − 1 çarpan değildir.'),
  ('Son üç terimi −(x + 1)² olarak toplanabilen x⁴ − x² − 2x − 1 ifadesi iki ikinci derece çarpana nasıl ayrılır?', '(x² − x − 1)(x² + x + 1)', ['(x² − x + 1)(x² + x − 1)', '(x² − 1)(x² − 2x − 1)', '(x − 1)²(x + 1)²'], 'Son üç terim −(x² + 2x + 1) = −(x + 1)²\'dir. İki kare farkıyla (x² − x − 1)(x² + x + 1) bulunur.'),
  ('P(x) = x² − 2 olmak üzere P(P(x)) = 0 denkleminin kaç gerçek kökü vardır?', '4', ['2', '0', '1'], 'P(P(x)) = (x² − 2)² − 2 = 0 için x² − 2 = ±√2, yani x² = 2 + √2 ya da 2 − √2 olur. İkisi de pozitif olduğundan dört gerçek kök vardır.'),
  ('Bir polinomun belirli bir aralıktaki farklı gerçek köklerinin sayısını, bir polinom dizisindeki işaret değişimlerini sayarak tam olarak veren teorem hangisidir?', 'Sturm teoremi', ['Rolle teoremi', 'Bézout teoremi', 'Ara değer teoremi'], 'Jacques Charles François Sturm\'ün 1829\'da verdiği teorem, Descartes kuralından farklı olarak kök sayısının yalnız üst sınırını değil kesin değerini verir.'),
  ('Derecesi m ve n olan iki düzlem eğrisinin ortak noktalarının sayısının (uygun koşullarla sayıldığında) m·n olduğunu söyleyen teorem hangi matematikçinin adıyla anılır?', 'Étienne Bézout', ['Blaise Pascal', 'Pierre de Fermat', 'Gaspard Monge'], 'Bézout teoremi, 1779\'da yayımlanan çalışmasıyla bilinir; örneğin iki farklı çember (ikinci dereceden) en çok 2·2 = 4 noktada kesişebilir sayılır.'),
  ('Rakamları farklı iki basamaklı ab sayısı ile rakamları yer değiştirmiş ba sayısının kareleri farkı her zaman hangi sayının katıdır?', '99', ['198', '100', '81'], '(10a + b)² − (10b + a)² = (9a − 9b)(11a + 11b) = 99(a − b)(a + b) olur.'),
  ('n bir tam sayı olmak üzere n⁴ − n² ifadesi her zaman aşağıdakilerden hangisine bölünür?', '12', ['24', '8', '18'], 'n⁴ − n² = n·n·(n − 1)(n + 1) olur. (n − 1)n(n + 1) 3\'e, n²(n² − 1) de 4\'e bölünür; sonuç 12\'nin katıdır. n = 2 için 12 çıktığından daha büyük bir sabit garanti edilemez.'),
  ('Terslerin farkının terslerin kareleri farkına bölümü olan (1/a − 1/b)/(1/a² − 1/b²) kesri (a, b ≠ 0, a ≠ ±b) sadeleşince ne olur?', 'ab/(a + b)', ['(a + b)/ab', 'ab/(b − a)', 'a + b'], 'Pay (b − a)/ab, payda (b − a)(b + a)/a²b²\'dir. Bölüm ab/(a + b) olur.'),
  ('Birbirinden farklı a ve b sayıları için a + 1/a = b + 1/b ise ab çarpımı kaçtır?', '1', ['−1', '0', '2'], '(a − b) + (b − a)/ab = (a − b)(1 − 1/ab) = 0 olur. a ≠ b olduğundan 1/ab = 1 ve ab = 1\'dir.'),
  ('İki değişkenli her simetrik polinomun x + y ve xy cinsinden tek türlü yazılabileceğini söyleyen sonuç hangisidir?', 'Simetrik polinomların temel teoremi', ['Cebirin temel teoremi', 'Kalan teoremi', 'Rasyonel kök teoremi'], 'Bu teorem genel olarak, her simetrik polinomun temel simetrik polinomlar cinsinden tek türlü bir polinom olarak yazılabileceğini söyler; örneğin x² + y² = (x + y)² − 2xy.'),
  ('P(x, y) üçüncü dereceden homojen bir polinomdur. P(2x, 2y) ifadesi P(x, y) cinsinden neye eşittir?', '8·P(x, y)', ['2·P(x, y)', '6·P(x, y)', 'P(x, y) + 8'], 'Homojen polinomun her terimi üçüncü derecedendir; x ve y 2 ile çarpılınca her terim 2³ = 8 katına çıkar.'),
  ('Toplamları 6, ikişerli çarpımlarının toplamı 11, çarpımları 6 olan üç sayının küpleri toplamı, a³ + b³ + c³ − 3abc özdeşliğiyle hesaplanırsa kaç bulunur?', '36', ['18', '216', '54'], 'a³ + b³ + c³ = 3abc + (a + b + c)[(a + b + c)² − 3(ab + bc + ca)] = 18 + 6·(36 − 33) = 36. (Sayılar 1, 2, 3\'tür: 1 + 8 + 27 = 36.)'),
  ('Pozitif a, b, c gerçek sayıları için a³ + b³ + c³ = 3abc ise hangisi kesinlikle doğrudur?', 'a = b = c', ['a + b + c = 0', 'abc = 1', 'a = b ve c = 0'], 'Fark (a + b + c)·½[(a − b)² + (b − c)² + (c − a)²]\'dir. Pozitif sayılarda ilk çarpan sıfır olamaz; o hâlde kareler toplamı sıfırdır ve a = b = c\'dir.'),
  ('Derecesi en çok 3 olan bir P(x) polinomu için P(0) = P(1) = P(2) = 1 ve P(3) = 2\'dir. P(4) kaçtır?', '5', ['2', '3', '4'], 'P(x) − 1 polinomu 0, 1, 2\'de sıfırdır: P(x) = 1 + k·x(x − 1)(x − 2). P(3) = 1 + 6k = 2\'den k = 1/6 ve P(4) = 1 + 24/6 = 5.'),
  ('(x³ − 1)⁴ ifadesinden x¹² çıkarıldığında en yüksek dereceli terimler sadeleşiyor. Geriye kalan polinomun derecesi kaçtır?', '9', ['12', '3', '8'], '(x³ − 1)⁴ = x¹² − 4x⁹ + ⋯ olduğundan x¹² terimleri birbirini götürür; en yüksek terim −4x⁹ olur.'),
  ('Aşağıdakilerden hangisi x⁹ + 1 polinomunu tam bölmez?', 'x² + 1', ['x + 1', 'x³ + 1', 'x² − x + 1'], '9, 3\'ün tek katı olduğundan x⁹ + 1 = (x³)³ + 1 ifadesi x³ + 1\'e, dolayısıyla x + 1 ve x² − x + 1\'e bölünür. x = i için i⁹ + 1 = i + 1 ≠ 0 olduğundan x² + 1 bölmez.'),
  ('Toplamın dördüncü kuvvetinden farkın dördüncü kuvveti çıkarılırsa, yani (a + b)⁴ − (a − b)⁴ sadeleştirilirse ne elde edilir?', '8ab(a² + b²)', ['8ab', '4ab(a² + b²)', '8a³b'], 'İki kare farkıyla [(a + b)² − (a − b)²][(a + b)² + (a − b)²] = 4ab·2(a² + b²) = 8ab(a² + b²).'),
  ('Toplamları 2 ve kareleri toplamı da 2 olan iki gerçek sayının yüzüncü kuvvetleri toplanırsa sonuç ne olur?', '2', ['2¹⁰⁰', '1', '4'], '2xy = 4 − 2 = 2\'den xy = 1; (x − y)² = 2 − 2 = 0 olduğundan x = y = 1\'dir. Toplam 1 + 1 = 2.'),
  ('x⁴ − 4x³ + 6x² − 4x ifadesi (x − 1)⁴ − 1 biçiminde yazılarak çarpanlarına ayrılırsa hangisi elde edilir?', 'x(x − 2)(x² − 2x + 2)', ['x(x − 2)³', '(x − 1)³(x − 2)', 'x(x + 2)(x² + 2x + 2)'], '(x − 1)⁴ − 1 = [(x − 1)² − 1][(x − 1)² + 1] = (x² − 2x)(x² − 2x + 2) = x(x − 2)(x² − 2x + 2).'),
  ('x² − y² = n eşitliğini sağlayan x, y tam sayıları bulunmayan n doğal sayıları hangi biçimdedir?', '4k + 2', ['4k', '4k + 1', '4k + 3'], 'x − y ile x + y aynı tek-çiftliktedir: ikisi de tekse çarpım tek, ikisi de çiftse çarpım 4\'ün katıdır. Bu yüzden 4\'e bölümünden 2 kalan sayılar iki karenin farkı olamaz.'),
  ('Katsayıları tam sayı olmadığı hâlde her tam sayı x için tam sayı değer alan bir polinom aşağıdakilerden hangisidir?', 'x(x + 1)/2', ['x/2', '(x² + 1)/2', 'x²/2'], 'x(x + 1) ardışık iki tam sayının çarpımı olduğundan çifttir; yarısı her zaman tam sayıdır. Diğerleri örneğin x = 1\'de tam sayı vermez.'),
  ('x⁵ + x⁴ + 1 polinomunun ikinci dereceden tam sayı katsayılı çarpanı aşağıdakilerden hangisidir?', 'x² + x + 1', ['x² − x + 1', 'x² + 1', 'x² + x − 1'], 'x² + x + 1\'in kökü ω için ω³ = 1 olduğundan ω⁵ + ω⁴ + 1 = ω² + ω + 1 = 0 olur. Gerçekten x⁵ + x⁴ + 1 = (x² + x + 1)(x³ − x + 1)\'dir.'),
  ('n⁵ − 5n³ + 4n ifadesi n(n² − 1)(n² − 4) biçiminde ayrılınca ardışık beş tam sayının çarpımı ortaya çıkıyor. Bu ifadenin her tam sayı n için kesinlikle bölündüğü en büyük sayı hangisidir?', '120', ['60', '240', '720'], 'n⁵ − 5n³ + 4n = (n − 2)(n − 1)n(n + 1)(n + 2) ardışık beş tam sayının çarpımıdır ve 5! = 120\'ye bölünür. n = 3 için değer tam 120 olduğundan daha büyük bir sayı her zaman bölmez.'),
  ('[−1, 1] aralığında birbirine dik olan ve fizikte küresel potansiyel açılımlarında ortaya çıkan polinom ailesi hangi matematikçinin adını taşır?', 'Legendre', ['Chebyshev', 'Lagrange', 'Newton'], 'Adrien-Marie Legendre\'nin adını taşıyan bu polinomlar P₀ = 1, P₁ = x, P₂ = (3x² − 1)/2 biçiminde başlar.'),
  ('Bilgisayar grafiklerinde kullanılan Bézier eğrilerinin temelini oluşturan polinom ailesi hangisidir?', 'Bernstein polinomları', ['Legendre polinomları', 'Hermite polinomları', 'Chebyshev polinomları'], 'Bézier eğrileri, kontrol noktalarının Bernstein temel polinomlarıyla ağırlıklandırılmış toplamıdır; Sergei Bernstein bu polinomları 1912\'de tanıtmıştır.'),
  ('x³ − 3x²y + 3xy² − y³ + 1 ifadesinin birinci dereceden çarpanı hangisidir?', 'x − y + 1', ['x − y − 1', 'x + y + 1', 'x − y'], 'İlk dört terim (x − y)³\'tür. (x − y)³ + 1 bir küp toplamıdır ve x − y + 1 çarpanını içerir.'),
  ('(x² + kx + 1)(x² − kx + 1) = x⁴ + 1 özdeşliğinin sağlanması için k² kaç olmalıdır?', '2', ['1', '4', '0'], 'Çarpım (x² + 1)² − k²x² = x⁴ + (2 − k²)x² + 1\'dir. x² teriminin yok olması için k² = 2 gerekir.'),
  ('x² − 2|x| + 1 ifadesi her gerçek x için hangi ifadenin karesine eşittir?', '|x| − 1', ['x − 1', 'x + 1', '|x − 1|'], 'x² = |x|² olduğundan ifade |x|² − 2|x| + 1 = (|x| − 1)²\'dir. Örneğin x = −3 için 9 − 6 + 1 = 4 = (3 − 1)²; (x − 1)² ise 16 verir.'),
];
